const body = $json.body ?? $json;

const empleado = String(body.empleado ?? '').trim();
const area = String(body.area ?? '').trim();
const consulta = String(body.consulta ?? '').trim();
const emailDestino = String(body.email_destino ?? '').trim();

const camposFaltantes = [];

if (!empleado) camposFaltantes.push('empleado');
if (!area) camposFaltantes.push('area');
if (!consulta) camposFaltantes.push('consulta');
if (!emailDestino) camposFaltantes.push('email_destino');

const formatoEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (emailDestino && !formatoEmail.test(emailDestino)) {
  camposFaltantes.push('email_destino_invalido');
}

return [
  {
    json: {
      id_consulta: `CONS-${Date.now()}`,
      fecha_hora: new Date().toISOString(),
      empleado,
      area,
      consulta,
      email_destino: emailDestino,
      campos_validos: camposFaltantes.length === 0,
      campos_faltantes: camposFaltantes,
      error: camposFaltantes.length
        ? `Faltan campos obligatorios o son inválidos: ${camposFaltantes.join(', ')}`
        : ''
    }
  }
];

const entrada = $('Validar entrada').first().json;
const itemsNotion = $input.all();

const procedimientos = itemsNotion.map((item) => {
  const dato = item.json;

  return {
    procedimiento:
      dato.name ??
      dato.property_procedimiento ??
      '',

    id:
      dato.property_id ??
      '',

    area:
      dato.property_área ??
      dato.property_area ??
      '',

    categoria:
      dato.property_categoría ??
      dato.property_categoria ??
      '',

    palabras_clave:
      dato.property_palabras_clave ??
      [],

    contenido:
      dato.property_contenido ??
      '',

    fuente:
      dato.property_fuente ??
      '',

    requiere_escalamiento:
      dato.property_requiere_escalamiento ??
      false
  };
});

const contexto = procedimientos
  .map((p, index) => {
    return [
      `PROCEDIMIENTO ${index + 1}`,
      `Nombre: ${p.procedimiento}`,
      `ID: ${p.id}`,
      `Área: ${p.area}`,
      `Categoría: ${p.categoria}`,
      `Palabras clave: ${Array.isArray(p.palabras_clave)
        ? p.palabras_clave.join(', ')
        : p.palabras_clave}`,
      `Contenido: ${p.contenido}`,
      `Fuente: ${p.fuente}`,
      `Requiere escalamiento: ${p.requiere_escalamiento ? 'Sí' : 'No'}`
    ].join('\n');
  })
  .join('\n\n---\n\n');

return [
  {
    json: {
      ...entrada,
      cantidad_procedimientos: procedimientos.length,
      procedimientos,
      contexto
    }
  }
];

const entrada = $('Preparar contexto para GPT').first().json;
const salidaOpenAI = $json;

let respuestaGPT = salidaOpenAI;

// Buscar la respuesta estructurada en los posibles formatos de OpenAI
if (!salidaOpenAI.respuesta) {
  const contenido =
    salidaOpenAI.output_text ??
    salidaOpenAI.text ??
    salidaOpenAI.message ??
    salidaOpenAI.output?.[0]?.content?.[0]?.text ??
    salidaOpenAI.choices?.[0]?.message?.content;

  if (typeof contenido === 'string') {
    const textoLimpio = contenido
      .replace(/^```json\s*/i, '')
      .replace(/```$/i, '')
      .trim();

    respuestaGPT = JSON.parse(textoLimpio);
  } else if (contenido && typeof contenido === 'object') {
    respuestaGPT = contenido;
  }
}

return [
  {
    json: {
      ...entrada,
      respuesta: respuestaGPT.respuesta,
      fuente: respuestaGPT.fuente,
      nivel_confianza: respuestaGPT.nivel_confianza,
      requiere_intervencion_humana:
        respuestaGPT.requiere_intervencion_humana,
      motivo_intervencion:
        respuestaGPT.motivo_intervencion
    }
  }
];

const datosOriginales = $('Normalizar respuesta GPT').first().json;
const resultadoGmail = $json.data ?? $json;

const aprobado = resultadoGmail.approved === true;

return [
  {
    json: {
      ...datosOriginales,
      requirio_aprobacion: true,
      aprobado,
      resultado_aprobacion: aprobado ? 'Aprobada' : 'Rechazada',
      fecha_respuesta_aprobacion:
        resultadoGmail.respondedAt ?? new Date().toISOString()
    }
  }
];

return [
  {
    json: {
      ...$json,
      requirio_aprobacion: false,
      aprobado: null,
      resultado_aprobacion: 'No aplica',
      estado: 'Respondida',
      respuesta_final: $json.respuesta,
      error: ''
    }
  }
];

return [
  {
    json: {
      ...$json,
      estado: 'Respondida',
      resultado_aprobacion: 'Rechazada',
      respuesta_final:
        'La respuesta propuesta fue rechazada por el responsable. El caso requiere revisión manual antes de responder al empleado.',
      error: ''
    }
  }
];

const dato = $json;
const entrada = $('Validar entrada').first().json;

function obtener(...nombres) {
  for (const nombre of nombres) {
    if (dato[nombre] !== undefined && dato[nombre] !== null) {
      return dato[nombre];
    }
  }

  return '';
}

const resultadoAprobacion = obtener(
  'property_resultado_de_aprobación',
  'property_resultado_de_aprobacion'
);

const respuestaGenerada = obtener(
  'property_respuesta_generada'
);

const respuestaFinal =
  resultadoAprobacion === 'Rechazada'
    ? 'La respuesta propuesta fue rechazada por el responsable. El caso requiere revisión manual antes de comunicar una respuesta definitiva.'
    : respuestaGenerada;

return [
  {
    json: {
      id_consulta:
        dato.name ??
        obtener('property_id_de_consulta'),

      empleado:
        obtener('property_empleado'),

      area:
        obtener('property_área', 'property_area'),

      consulta:
        obtener('property_consulta'),

      respuesta:
        respuestaFinal,

      fuente:
        obtener('property_fuente_consultada'),

      nivel_confianza:
        obtener('property_nivel_de_confianza'),

      requirio_aprobacion:
        obtener(
          'property_requirió_aprobación',
          'property_requirio_aprobacion'
        ),

      resultado_aprobacion:
        resultadoAprobacion,

      estado:
        obtener('property_estado'),

      email_destino:
        entrada.email_destino
    }
  }
];

return [
  {
    json: {
      ...$json,
      area: $json.area || 'General',
      respuesta: '',
      fuente: 'No aplica',
      nivel_confianza: 'Bajo',
      requiere_intervencion_humana: false,
      motivo_intervencion: 'Faltan datos obligatorios',
      requirio_aprobacion: false,
      resultado_aprobacion: 'No aplica',
      estado: 'Error',
      respuesta_final: '',
      error: $json.error || 'La solicitud contiene datos incompletos'
    }
  }
];

