const entrada = $('Validar entrada').first().json;

const detalleError =
  $json.error?.message ??
  $json.message ??
  $json.description ??
  'Fallo no identificado en la API de OpenAI';

return [
  {
    json: {
      ...entrada,
      area: entrada.area || 'General',
      respuesta: '',
      fuente: 'OpenAI API',
      nivel_confianza: 'Bajo',
      requiere_intervencion_humana: false,
      motivo_intervencion: 'Fallo de la API de OpenAI',
      requirio_aprobacion: false,
      resultado_aprobacion: 'No aplica',
      estado: 'Error',
      respuesta_final: '',
      error: `Error de OpenAI: ${detalleError}`
    }
  }
];

